parameters.text:
=CUSTOMER ACCOUNT CONTEXT:
- Company: {{ $('Lookup Customer').item.json.fields.Company_Name || 'Unknown / New Customer' }}
- Account Tier: {{ $('Lookup Customer').item.json.fields.Account_Tier || 'Free Starter' }}
- Lifetime Value: ${{ $('Lookup Customer').item.json.fields.Lifetime_Value_USD || 0 }}
- Assigned Executive: {{ $('Lookup Customer').item.json.fields.Assigned_Executive || 'Support Team' }}

INCIDENT REPORT:
- Incident ID: {{ $('Clean & Sanitize Inputs').item.json.incident_id }}
- Subject: {{ $('Clean & Sanitize Inputs').item.json.subject }}
- Message: {{ $('Clean & Sanitize Inputs').item.json.raw_message }}
- Timestamp: {{ $('Clean & Sanitize Inputs').item.json.timestamp }}

RELEVANT KNOWLEDGE BASE SOLUTIONS (up to 3, keyword-matched to this report):
{{ (() => { const stop = ['the','and','for','not','out','too','you','are']; const tok = s => String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length >= 3 && !stop.includes(w)); const c = $('Clean & Sanitize Inputs').item.json; const words = new Set(tok(c.subject + ' ' + c.raw_message)); const hits = $('Fetch Knowledge Base').all().map(i => i.json.fields || {}).filter(f => f.Topic).map(f => ({ f, score: [...new Set(tok(f.Keywords))].filter(w => words.has(w)).length })).filter(x => x.score > 0).sort((a, b) => b.score - a.score).slice(0, 3); return hits.length ? hits.map(x => 'KB Article: ' + x.f.Topic + '\nKeywords: ' + x.f.Keywords + '\nSolution: ' + x.f.Verified_Solution).join('\n---\n') : 'No matching knowledge base article found. Do not invent a solution; say the team is investigating.'; })() }}

parameters.inputSchema:
={
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": ["Outage / Critical Bug", "Billing & Invoicing", "Feature Request", "General FAQ"],
      "description": "Primary issue category"
    },
    "sentiment_score": {
      "type": "integer",
      "description": "1 (Furious / Threatening cancellation) to 5 (Polite / Delighted)"
    },
    "churn_risk": {
      "type": "string",
      "enum": ["High Churn Threat", "Normal"],
      "description": "Flag as High Churn Threat if customer threatens leaving or is losing money"
    },
    "urgency_level": {
      "type": "string",
      "enum": ["P1 - Critical", "P2 - High", "P3 - Standard"],
      "description": "P1 for active outages or VIP churn threats; P2 for billing issues; P3 for general FAQs"
    },
    "technical_bug_detected": {
      "type": "boolean",
      "description": "True if an engineering code bug, 500 error, or API crash was reported"
    },
    "resolution_draft": {
      "type": "string",
      "description": "Professional, empathetic customer resolution. If a KB article matches, quote its instructions."
    },
    "internal_summary": {
      "type": "string",
      "description": "One concise sentence summarizing the incident for executives"
    }
  },
  "required": ["category", "sentiment_score", "churn_risk", "urgency_level", "technical_bug_detected", "resolution_draft", "internal_summary"]
}

